const contractSteps=['Dados Básicos','Dados do Cliente','Dados Financeiros'];
const contractNewClients=quoteLoad('docfreela-contract-clients-v1',[]);for(const c of contractNewClients){if(!clientsState.items.some(x=>x.id===c.id))clientsState.items.push(c)}
const contractPayment=['PIX','Boleto','Cartão de crédito','Transferência bancária','Dinheiro','Outro'];
const contractField=(name,label,value='',extra='')=>`<label>${label}<input name="${name}" value="${esc(value)}" ${extra}></label>`;
const contractTemplateOptions=()=>`<option value="default">Template Padrão (padrão)</option>${quoteState.pdf.models.filter(x=>x.id!=='default').map(x=>`<option value="${esc(x.id)}">${esc(x.title)}</option>`).join('')}`;
function contractClientFill(form,clientId){const c=clientsState.items.find(x=>x.id===clientId);if(!c)return;const map={legalName:c.legalName||c.company||c.name,representative:c.representative||c.name,document:c.document||'',email:c.email||'',phone:c.phone||'',street:c.street||'',number:c.number||'',district:c.district||'',city:c.city||'',state:c.state||''};for(const [name,value] of Object.entries(map))form.elements.namedItem(name).value=value;const project=form.elements.namedItem('title');if(!project.value)project.value=c.project||''}
function contractUpdateFinal(form){const gross=Number(form.elements.namedItem('gross').value)||0,discount=Number(form.elements.namedItem('discount').value)||0;form.elements.namedItem('amount').value=money(Math.max(0,gross-discount));form.querySelector('#contract-discount-error').textContent=discount>gross?'O desconto não pode superar o valor total.':''}
function contractGo(layer,step,skipValidation=false){const form=layer.querySelector('#contract-wizard-form');if(step>Number(layer.dataset.step)&&!skipValidation){const current=layer.querySelector('.contract-step:not([hidden])');const required=[...current.querySelectorAll('[required]')];for(const field of required){if(!field.checkValidity()){field.reportValidity();field.focus();return}}if(Number(layer.dataset.step)===2){const gross=Number(form.elements.namedItem('gross').value)||0,discount=Number(form.elements.namedItem('discount').value)||0;if(discount>gross){form.querySelector('#contract-discount-error').textContent='O desconto não pode superar o valor total.';return}}}layer.dataset.step=String(step);layer.querySelectorAll('.contract-step').forEach((section,i)=>section.hidden=i!==step);layer.querySelectorAll('.contract-tabs button').forEach((button,i)=>{button.classList.toggle('active',i===step);button.setAttribute('aria-current',i===step?'step':'false')});layer.querySelector('[data-contract="back"]').hidden=step===0;layer.querySelector('[data-contract="next"]').hidden=step===2;layer.querySelector('[data-contract="save"]').hidden=step!==2;layer.querySelector('.contract-step:not([hidden]) input, .contract-step:not([hidden]) select')?.focus()}
quoteContractForm=function(q){const related=q&&quoteClient(q),layer=document.createElement('div');layer.className='quote-dialog contract-wizard';layer.dataset.step='0';layer.dataset.quoteId=q?.id||'';layer.innerHTML=`<div class="quote-dialog-card" role="dialog" aria-modal="true" aria-label="Novo Contrato"><header><h2>Novo Contrato</h2><button type="button" data-quote="close" aria-label="Fechar">×</button></header><nav class="contract-tabs" aria-label="Etapas do contrato">${contractSteps.map((x,i)=>`<button type="button" data-contract="step" data-step="${i}" class="${i===0?'active':''}" aria-current="${i===0?'step':'false'}">${x}</button>`).join('')}</nav><form id="contract-wizard-form" novalidate><section class="contract-step"><label>Modelo de contrato<select name="template">${contractTemplateOptions()}</select></label><div class="contract-client-line"><label>Cliente *<select name="clientId" required><option value="">Selecione o cliente</option>${clientsState.items.filter(c=>!c.archived).map(c=>`<option value="${esc(c.id)}" ${q?.clientId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><button type="button" data-contract="new-client" aria-label="Cadastrar novo cliente" title="Cadastrar novo cliente">＋</button></div>${contractField('title','Nome do Projeto *',q?.title||related?.project||'','required maxlength="160" placeholder="Ex: Identidade Visual Completa"')}<label>Serviços Inclusos <small>Listar item a item</small><textarea name="services" rows="3" placeholder="Descreva os serviços que serão prestados...">${esc(q?.items?.map(x=>x.name+(x.description?' — '+x.description:'')).join('\n')||'')}</textarea></label><div class="quote-form-grid">${contractField('delivery','Prazo de entrega',q?.delivery||'','placeholder="Ex: 30/12/2026 ou 30 dias"')}${contractField('duration','Duração do Contrato',related?.months?related.months+' meses a partir da assinatura':'','placeholder="90 dias a partir da assinatura"')}</div></section><section class="contract-step" hidden><div class="quote-form-grid">${contractField('legalName','Nome/Razão Social',related?.legalName||related?.company||q?.clientName||'')}${contractField('representative','Representante',related?.representative||'')}${contractField('document','CPF/CNPJ',related?.document||'','placeholder="000.000.000-00"')}${contractField('email','E-mail',q?.clientEmail||related?.email||'','type="email" placeholder="email@cliente.com"')}${contractField('phone','Telefone/WhatsApp',related?.phone||'')}${contractField('street','Endereço',related?.street||'')}${contractField('number','Número',related?.number||'')}${contractField('district','Bairro',related?.district||'')}${contractField('city','Cidade',related?.city||'')}</div>${contractField('state','Estado',related?.state||'','maxlength="2" placeholder="Ex: SC"')}</section><section class="contract-step" hidden><div class="quote-form-grid">${contractField('gross','Valor Total *',q?quoteTotal(q):'','type="number" required min="0.01" step="0.01" placeholder="R$ 5.000,00"')}${contractField('discount','Desconto',0,'type="number" min="0" step="0.01" placeholder="R$ 0,00"')}${contractField('amount','Valor Final','','readonly aria-label="Valor final"')}${contractField('installments','Parcelas',1,'type="number" required min="1" max="120" step="1"')}</div><div class="quote-form-grid"><label>Forma de Pagamento<select name="paymentMethod">${contractPayment.map(x=>`<option>${x}</option>`).join('')}</select></label>${contractField('paymentTerms','Condições de Pagamento',q?.payment||'À vista')}</div><p class="contract-error" id="contract-discount-error" role="alert"></p></section><footer class="contract-footer"><button type="button" data-quote="close">Cancelar</button><span></span><button type="button" data-contract="back" hidden>‹ &nbsp; Voltar</button><button type="button" class="primary" data-contract="next">Próximo &nbsp; ›</button><button type="submit" class="primary" data-contract="save" hidden>Gerar Contrato</button></footer></form></div>`;document.body.append(layer);contractUpdateFinal(layer.querySelector('form'));layer.querySelector('input,select')?.focus()};
function contractText(c){const lines=[`CONTRATO DE PRESTAÇÃO DE SERVIÇOS`,``,`CONTRATANTE: ${c.legalName||c.clientName}${c.document?', CPF/CNPJ '+c.document:''}${c.representative?', representado(a) por '+c.representative:''}.`,`Contato: ${[c.email,c.phone].filter(Boolean).join(' · ')||'Não informado'}.`,`Endereço: ${[c.street,c.number,c.district,c.city,c.state].filter(Boolean).join(', ')||'Não informado'}.`,``,`1. OBJETO`,`O presente contrato tem por objeto ${c.title}.`,c.services?`Serviços inclusos:\n${c.services}`:'',``,`2. PRAZO`,c.delivery?`Prazo de entrega: ${c.delivery}.`:'Prazo de entrega: conforme acordado pelas partes.',c.duration?`Duração do contrato: ${c.duration}.`:'',``,`3. VALOR E PAGAMENTO`,`Valor total: ${money(c.gross)}.`,c.discount?`Desconto: ${money(c.discount)}.`:'',`Valor final: ${money(c.amount)}.`,`Pagamento: ${c.installments} ${Number(c.installments)===1?'parcela':'parcelas'} via ${c.paymentMethod}. ${c.paymentTerms||''}`,``,`4. CONDIÇÕES`,c.terms||'As partes acordam com as condições apresentadas na proposta vinculada.',``,`Data de emissão: ${formatDate(c.date)}.`,``,`________________________________       ________________________________`,`Contratante                                      Contratada`];return lines.filter(x=>x!==undefined).join('\n')}
quoteContractPreview=function(id){const c=quoteState.contracts.find(x=>x.id===id);if(!c)return;const content=contractText(c);quoteModal('Contrato · '+c.clientName,`<div class="quote-contract-document"><pre>${esc(content)}</pre></div><div class="quote-dialog-actions"><button data-quote="close">Fechar</button><button data-quote="print-contract" data-id="${esc(id)}">Imprimir / salvar PDF</button></div>`)};
document.addEventListener('click',e=>{const b=e.target.closest('[data-contract]');if(!b)return;const layer=b.closest('.contract-wizard');if(!layer)return;const step=Number(layer.dataset.step);if(b.dataset.contract==='next')contractGo(layer,Math.min(2,step+1));else if(b.dataset.contract==='back')contractGo(layer,Math.max(0,step-1));else if(b.dataset.contract==='step')contractGo(layer,Number(b.dataset.step),true);else if(b.dataset.contract==='new-client'){const form=layer.querySelector('form');form.elements.namedItem('clientId').value='';form.elements.namedItem('clientId').required=false;form.elements.namedItem('legalName').required=true;contractGo(layer,1,true);form.elements.namedItem('legalName').focus();toast('Preencha os dados do novo cliente. Ele será cadastrado ao gerar o contrato.')}});
document.addEventListener('change',e=>{if(e.target.matches('.contract-wizard [name="clientId"]'))contractClientFill(e.target.form,e.target.value)});
document.addEventListener('input',e=>{if(e.target.matches('.contract-wizard [name="gross"],.contract-wizard [name="discount"]'))contractUpdateFinal(e.target.form)});
document.addEventListener('submit',e=>{if(e.target.id!=='contract-wizard-form')return;e.preventDefault();const layer=e.target.closest('.contract-wizard');if(layer.dataset.step!=='2'){contractGo(layer,Number(layer.dataset.step)+1);return}const required=[...e.target.querySelectorAll('[required]')];for(const field of required){if(!field.checkValidity()){const section=field.closest('.contract-step');contractGo(layer,[...e.target.querySelectorAll('.contract-step')].indexOf(section),true);field.reportValidity();field.focus();return}}const f=new FormData(e.target),gross=Number(f.get('gross'))||0,discount=Number(f.get('discount'))||0;if(gross<=0||discount<0||discount>gross){contractUpdateFinal(e.target);return}let clientId=String(f.get('clientId')||''),client=clientsState.items.find(x=>x.id===clientId);if(!client){const name=String(f.get('legalName')||'').trim();if(!name){contractGo(layer,1);e.target.elements.namedItem('legalName').required=true;e.target.elements.namedItem('legalName').reportValidity();return}clientId=crypto.randomUUID();client={id:clientId,name,company:name,email:String(f.get('email')||''),phone:String(f.get('phone')||''),project:String(f.get('title')||''),pipeline:'Pipeline Principal',stage:'Novo Lead',start:quoteToday(),months:'',monthly:0,tags:[],archived:false,contacts:[]};clientsState.items.push(client);contractNewClients.push(client);localStorage.setItem('docfreela-contract-clients-v1',JSON.stringify(contractNewClients))}const data={id:crypto.randomUUID(),quoteId:layer.dataset.quoteId||null,clientId,clientName:client.name,title:String(f.get('title')||'').trim(),services:String(f.get('services')||'').trim(),delivery:String(f.get('delivery')||'').trim(),duration:String(f.get('duration')||'').trim(),legalName:String(f.get('legalName')||'').trim(),representative:String(f.get('representative')||'').trim(),document:String(f.get('document')||'').trim(),email:String(f.get('email')||'').trim(),phone:String(f.get('phone')||'').trim(),street:String(f.get('street')||'').trim(),number:String(f.get('number')||'').trim(),district:String(f.get('district')||'').trim(),city:String(f.get('city')||'').trim(),state:String(f.get('state')||'').trim().toUpperCase(),gross,discount,amount:gross-discount,installments:Number(f.get('installments'))||1,paymentMethod:String(f.get('paymentMethod')||'PIX'),paymentTerms:String(f.get('paymentTerms')||'').trim(),template:String(f.get('template')||'default'),terms:quoteState.pdf.models.find(x=>x.id===f.get('template'))?.body||quoteState.pdf.models.find(x=>x.default)?.body||'',status:'rascunho',date:quoteToday()};quoteState.contracts.unshift(data);quotePersist();if(typeof dashActivity==='function')dashActivity('Contrato gerado: '+data.title,clientId);layer.remove();quoteState.tab='Contratos';renderQuotes();toast('Contrato gerado e salvo.');quoteContractPreview(data.id)});
